const ALLOWED_CATEGORIES = new Set(Object.keys(CATEGORY_SUB_TAGS));

export const allTools = _rawAllTools
  .filter(t => ALLOWED_CATEGORIES.has(t.category))
  .map(t => {
    const allowed = CATEGORY_SUB_TAGS[t.category] || [];
    const keep = new Set<string>([t.category, ...t.tags.filter(tag => allowed.includes(tag))]);
    return { ...t, tags: Array.from(keep) };
  });
